declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/smart_city_v630.php';if(!sc630_enabled()){http_response_code(404);exit('Wallet unavailable.');}$u=sc630_require_user();$uid=(int)$u['id'];$flash='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();if(($_POST['action']??'')==='redeem'){$r=sc630_redeem_points($uid,(int)($_POST['points']??0));$flash='Points redeemed. New wallet balance: '.sc630_money((float)$r['balance']);}}}catch(Throwable $e){$err=$e->getMessage();}sc630_sync_user_rewards($uid);$a=sc630_wallet_ensure($uid);$ledger=sc630_wallet_ledger($uid,50);$rules=[];try{$q=db()->prepare('SELECT * FROM loyalty_rules_v630 WHERE status=1 AND tenant_id IN(0,?) ORDER BY points DESC');$q->execute([sc630_tid()]);$rules=$q->fetchAll()?:[];}catch(Throwable $e){}sc630_track('wallet','view');sc630_public_header('Citizen Wallet & Loyalty','Auditable ShahkotPK portal credits and loyalty points.');
