<div class="sc630-two"><section class="sc630-panel"><h2>Redeem Loyalty Points</h2><p><?=e(sc630_setting('smart_city_v630_points_per_rupee','10'))?> points = Rs 1 wallet credit. Minimum <?=e(sc630_setting('smart_city_v630_min_redeem_points','500'))?> points.</p><form method="post" class="sc630-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="redeem"><label>Points to redeem<input type="number" name="points" min="1" step="1" required></label><button class="sc630-btn primary">Convert to Wallet Credit</button></form></section><section class="sc630-panel"><h2>Ways to Earn</h2><?php foreach($rules as $r):?><div class="sc630-detail"><b>+<?=(int)$r['points']?> points · <?=e($r['name'])?></b><span>Daily limit: <?=(int)$r['max_per_day']?></span></div><?php endforeach;?></section></div>
<section class="sc630-panel"><div class="sc630-panel-head"><h2>Wallet Ledger</h2><span>Every adjustment has a transaction number</span></div><div class="sc630-table"><table><thead><tr><th>Date</th><th>Transaction</th><th>Category</th><th>Amount</th><th>Points</th><th>Balance</th></tr></thead><tbody><?php foreach($ledger as $x):?><tr><td><?=e(date('d M Y',strtotime($x['created_at'])))?></td><td><b><?=e($x['transaction_no'])?></b><small><?=e($x['note']?:'')?></small></td><td><?=e(ucwords(str_replace('_',' ',$x['category'])))?></td><td class="<?=$x['direction']==='credit'?'pos':'neg'?>"><?=$x['amount']>0?e(($x['direction']==='credit'?'+':'-').' '.sc630_money((float)$x['amount'])):'—'?></td><td><?=((int)$x['points_delta']>0?'+':'').number_format((int)$x['points_delta'])?></td><td><?=sc630_money((float)$x['balance_after'])?></td></tr><?php endforeach;?><?php if(!$ledger):?><tr><td colspan="6">No wallet activity yet.</td></tr><?php endif;?></tbody></table></div></section></div></main><?php sc630_public_footer(); ?>
